(function(E){ const x = E["exam-04"] = E["exam-04"] || {units:{}}; (x.units = x.units || {})["x04-w1"] = {"id":"x04-w1","patterns":["W1-mixed","W1-offer","REG-semi","PARA-letter","PARA-trend","TR-overview","TR-bullets"],"title":{"en":"Writing Task 1","tr":"Writing Task 1","fa":"Writing Task 1 (نوشتن، تکلیف ۱)"},"objective":{"en":"In this lesson you will learn to describe two visuals together, a bar chart that shows change over time and a table of percentages: one overview for both, then a paragraph for each, with the key figures compared, in at least 150 words.","tr":"Bu derste iki görseli birlikte anlatmayı öğreneceksin: zaman içindeki değişimi gösteren bir sütun grafik ve bir yüzde tablosu; ikisi için tek bir genel bakış, sonra her biri için bir paragraf ve karşılaştırılmış önemli rakamlar, en az 150 kelimeyle.","fa":"در این درس یاد می‌گیری دو تصویر را با هم توصیف کنی، یک نمودار میله‌ای که تغییر در طول زمان را نشان می‌دهد و یک جدول درصد: یک نمای کلی برای هر دو و بعد برای هر کدام یک پاراگراف با عددهای مهمِ مقایسه‌شده، در دست‌کم ۱۵۰ کلمه."},"objectiveGT":{"en":"In this lesson you will learn to write a semi-formal letter offering help: a polite, friendly tone for someone you know a little, one paragraph for each bullet point with exact details, and a suitable close, in at least 150 words.","tr":"Bu derste yardım teklif eden yarı resmî bir mektup yazmayı öğreneceksin: biraz tanıdığın biri için kibar ve samimi bir üslup, her madde için kesin ayrıntılarla bir paragraf ve uygun bir kapanış, en az 150 kelimeyle.","fa":"در این درس یاد می‌گیری یک نامه‌ی نیمه‌رسمی برای پیشنهاد کمک بنویسی: لحنی مؤدب و دوستانه برای کسی که کمی می‌شناسی‌اش، برای هر نکته یک پاراگراف با جزئیات دقیق و پایانی مناسب، در دست‌کم ۱۵۰ کلمه."},"sessions":[["explain"],["writing"],["exit"]],"explain":{"title":{"en":"Writing Task 1: a chart and a table","tr":"Writing Task 1: bir grafik ve bir tablo","fa":"Writing Task 1: یک نمودار و یک جدول"},"objective":{"en":"In this lesson you will learn to describe two visuals together, a bar chart that shows change over time and a table of percentages: one overview for both, then a paragraph for each, with the key figures compared, in at least 150 words.","tr":"Bu derste iki görseli birlikte anlatmayı öğreneceksin: zaman içindeki değişimi gösteren bir sütun grafik ve bir yüzde tablosu; ikisi için tek bir genel bakış, sonra her biri için bir paragraf ve karşılaştırılmış önemli rakamlar, en az 150 kelimeyle.","fa":"در این درس یاد می‌گیری دو تصویر را با هم توصیف کنی، یک نمودار میله‌ای که تغییر در طول زمان را نشان می‌دهد و یک جدول درصد: یک نمای کلی برای هر دو و بعد برای هر کدام یک پاراگراف با عددهای مهمِ مقایسه‌شده، در دست‌کم ۱۵۰ کلمه."},"stats":[{"label":{"en":"Words","tr":"Kelime","fa":"کلمه"},"value":"150+"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}},{"label":{"en":"Visuals","tr":"Görsel","fa":"تصویر"},"value":"2"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a sports-centre survey","tr":"Bu sınav: bir spor merkezi anketi","fa":"این آزمون: نظرسنجی یک مرکز ورزشی"},"intro":{"en":"Academic Task 1 is sometimes two visuals from the same survey. You do not have to connect every figure, but you must cover both visuals and give an overview of each.","tr":"Academic Task 1 bazen aynı anketten iki görseldir. Her rakamı birbirine bağlaman gerekmez ama iki görseli de ele almalı ve her birinin genel bakışını vermelisin.","fa":"Academic Task 1 گاهی دو تصویر از یک نظرسنجی است. لازم نیست همه‌ی عددها را به هم ربط بدهی، اما باید هر دو تصویر را پوشش بدهی و نمای کلی هر کدام را بگویی."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x04-w1-ctx","exam":true,"patterns":["W1-mixed","PARA-trend"],"often":{"pattern":"W1-mixed","n":6,"of":40,"label":{"en":"Comes up often in the real exam: 6 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"A chart and a table about a sports centre","tr":"Bir spor merkezi hakkında bir grafik ve bir tablo","fa":"یک نمودار و یک جدول درباره‌ی یک مرکز ورزشی"},"asks":{"en":"Two visuals from one survey: a bar chart of how often three age groups visited a sports centre over six years, and a table of how satisfied members were with five facilities. You summarise both and link them where it helps.","tr":"Tek bir anketten iki görsel: üç yaş grubunun altı yıl boyunca bir spor merkezine ne sıklıkla gittiğini gösteren bir sütun grafik ve üyelerin beş olanaktan ne kadar memnun olduğunu gösteren bir tablo. İkisini de özetler ve yararlı olduğunda bağlantı kurarsın.","fa":"دو تصویر از یک نظرسنجی: نمودار میله‌ای که نشان می‌دهد سه گروه سنی در شش سال چند بار به یک مرکز ورزشی رفته‌اند و جدولی که میزان رضایت اعضا از پنج امکانات را نشان می‌دهد. هر دو را خلاصه می‌کنی و هرجا کمک کند به هم وصلشان می‌کنی."},"fields":["Bar chart: three age groups","Four years","Table: five facilities","Highest and lowest"],"words":[{"a":"on average","b":"the average number","tr":"ortalama olarak","fa":"به‌طور میانگین"},{"a":"fell sharply","b":"dropped a lot","tr":"keskin biçimde düştü","fa":"به‌شدت کاهش یافت"},{"a":"recovered","b":"went back up","tr":"toparlandı","fa":"دوباره بالا رفت"},{"a":"doubled","b":"became twice as many","tr":"iki katına çıktı","fa":"دو برابر شد"},{"a":"remained steady","b":"stayed about the same","tr":"sabit kaldı","fa":"ثابت ماند"},{"a":"overtook","b":"became higher than","tr":"geçti","fa":"جلو زد"},{"a":"by far the most","b":"much more than any other","tr":"açık ara en çok","fa":"با فاصله‌ی زیاد بیشترین"},{"a":"satisfied","b":"happy with","tr":"memnun","fa":"راضی"},{"a":"just over half","b":"about 52%","tr":"yarıdan biraz fazla","fa":"کمی بیشتر از نصف"},{"a":"fewer than half","b":"below 50%","tr":"yarıdan az","fa":"کمتر از نصف"},{"a":"in contrast","b":"whereas / on the other hand","tr":"buna karşılık","fa":"در مقابل"},{"a":"respectively","b":"in the order given","tr":"sırasıyla","fa":"به ترتیب"}],"traps":[{"en":"Describing only one visual. A mixed task has two: give each its own paragraph, and mention both in the overview.","tr":"Yalnızca bir görseli anlatmak. Karma bir görevde iki görsel vardır: her birine ayrı bir paragraf ver ve genel bakışta ikisinden de söz et.","fa":"توصیف فقط یکی از تصویرها. تمرین ترکیبی دو تصویر دارد: به هر کدام یک پاراگراف بده و در نمای کلی از هر دو اسم ببر."},{"en":"Listing every number. Pick the highest, the lowest and the biggest changes, and compare them.","tr":"Her sayıyı sıralamak. En yükseği, en düşüğü ve en büyük değişiklikleri seç ve karşılaştır.","fa":"فهرست کردن همه‌ی عددها. بالاترین، پایین‌ترین و بزرگ‌ترین تغییرها را انتخاب و مقایسه کن."},{"en":"Different units. The chart shows visits; the table shows percentages. Do not mix them in one sentence as if they were the same measure.","tr":"Farklı birimler. Grafik ziyaretleri, tablo yüzdeleri gösteriyor. Aynı ölçüymüş gibi tek bir cümlede karıştırma.","fa":"واحدهای متفاوت. نمودار تعداد بازدید و جدول درصد را نشان می‌دهد. آن‌ها را در یک جمله طوری قاطی نکن که انگار یک معیارند."}],"example":{"text":"Chart: visits per month, 2018: 4, 2024: 8. Table: 90% satisfied with the pool.","item":"Write one sentence that links the two visuals.","answer":"Visits doubled from four to eight a month over the period, while 90% of members said they were satisfied with the pool.","why":{"en":"One figure from each visual, joined with \"and\", each with its own unit.","tr":"Her görselden bir rakam, \"and\" ile bağlanmış, her biri kendi birimiyle.","fa":"یک عدد از هر تصویر، با «and» به هم وصل، هر کدام با واحد خودش."}}},{"id":"W1-mixed","ctx":["W1-mixed"],"title":{"en":"Two visuals together","tr":"İki görsel bir arada","fa":"دو تصویر با هم"},"asks":{"en":"Two visuals on one topic: a chart and a table, a pie and a bar. You need one overview that links them, then a paragraph for each visual, with a comparison where they connect.","tr":"Tek bir konuda iki görsel: bir grafik ve bir tablo, bir pasta ve bir sütun grafik. İkisini bağlayan bir genel bakış, sonra her görsel için bir paragraf ve birleştikleri yerde bir karşılaştırma gerekir.","fa":"دو تصویر درباره‌ی یک موضوع: یک نمودار و یک جدول، یک نمودار دایره‌ای و یک میله‌ای. یک نمای کلی لازم است که این دو را به هم وصل کند، بعد یک پاراگراف برای هر تصویر، با مقایسه هرجا به هم ربط دارند."},"fields":["Introduction: what each visual shows","Overview: the main point of each visual, linked","Body 1: the first visual, grouped","Body 2: the second visual, linked back to the first"],"words":[{"a":"the first chart","b":"the bar chart / the table","tr":"ilk grafik","fa":"نمودار اول"},{"a":"shows","b":"illustrates / gives information about","tr":"gösterir","fa":"نشان می‌دهد"},{"a":"the second one","b":"the accompanying table","tr":"ikinci görsel","fa":"تصویر دوم"},{"a":"also","b":"similarly / likewise","tr":"benzer şekilde","fa":"به همین ترتیب"},{"a":"but","b":"in contrast / on the other hand","tr":"buna karşılık","fa":"در مقابل"},{"a":"part","b":"proportion / share","tr":"pay","fa":"سهم"},{"a":"most of","b":"the majority of","tr":"çoğu","fa":"بیشترِ"},{"a":"spending","b":"expenditure on","tr":"harcama","fa":"هزینه کردن"},{"a":"how many","b":"the number of","tr":"... sayısı","fa":"تعدادِ"},{"a":"how much","b":"the amount of","tr":"... miktarı","fa":"مقدارِ"},{"a":"this matches","b":"this is consistent with","tr":"bu ... ile örtüşüyor","fa":"این با ... هم‌خوان است"},{"a":"in total","b":"altogether","tr":"toplamda","fa":"در مجموع"}],"traps":[{"en":"Two separate reports: link the visuals in the overview, or the answer looks like two short tasks.","tr":"İki ayrı rapor: görselleri genel bakışta bağla, yoksa cevap iki kısa görev gibi görünür.","fa":"دو گزارش جدا: تصویرها را در نمای کلی به هم وصل کن، وگرنه جوابت مثل دو تکلیف کوتاه می‌شود."},{"en":"Number or amount: \"the number of people\" (you can count them), \"the amount of money\" (you cannot).","tr":"Sayı mı miktar mı: \"the number of people\" (sayılabilir), \"the amount of money\" (sayılamaz).","fa":"تعداد یا مقدار: «the number of people» (شمردنی)، «the amount of money» (نشمردنی)."}],"example":{"text":"Bar chart: library visits fell from 50,000 to 30,000 between 2010 and 2020. Table: e-book loans rose from 2,000 to 40,000 over the same period.","item":"Write an overview that links the two visuals.","answer":"Overall, visits to the library fell over the decade, while e-book loans rose sharply over the same period.","why":{"en":"One sentence, both visuals, the main trend of each, no detailed figures.","tr":"Tek cümle, iki görsel, her birinin ana eğilimi, ayrıntılı rakam yok.","fa":"یک جمله، هر دو تصویر، روند اصلی هر کدام، بدون عدد جزئی."}},"general":true,"patterns":["W1-mixed"],"often":{"pattern":"W1-mixed","n":6,"of":40,"label":{"en":"Comes up often in the real exam: 6 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"One overview, two body paragraphs","tr":"Bir genel bakış, iki gövde paragrafı","fa":"یک نمای کلی، دو پاراگراف بدنه"},"body":{"en":"Write at least 150 words in about 20 minutes: one sentence on what the two visuals show, an overview with the main point of each, a paragraph on the chart, and a paragraph on the table.","tr":"Yaklaşık 20 dakikada en az 150 kelime yaz: iki görselin neyi gösterdiğine dair bir cümle, her birinin ana noktasını veren bir genel bakış, grafik için bir paragraf ve tablo için bir paragraf.","fa":"در حدود ۲۰ دقیقه دست‌کم ۱۵۰ کلمه بنویس: یک جمله درباره‌ی اینکه دو تصویر چه نشان می‌دهند، نمای کلی با نکته‌ی اصلی هر کدام، یک پاراگراف برای نمودار و یک پاراگراف برای جدول."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"One main point from each visual","tr":"Her görselden bir ana nokta","fa":"از هر تصویر یک نکته‌ی اصلی"},"steps":[{"en":"Chart: find the group that changed most and the year where the pattern turned.","tr":"Grafik: en çok değişen grubu ve örüntünün döndüğü yılı bul.","fa":"نمودار: گروهی را که بیشتر از همه تغییر کرد و سالی را که الگو برگشت پیدا کن."},{"en":"Table: find the highest and the lowest figures and anything below half.","tr":"Tablo: en yüksek ve en düşük rakamları ve yarının altındaki her şeyi bul.","fa":"جدول: بالاترین و پایین‌ترین عدد و هر چیزی را که کمتر از نصف است پیدا کن."},{"en":"Put both main points in the overview, then support each in its own paragraph.","tr":"İki ana noktayı genel bakışa koy, sonra her birini kendi paragrafında destekle.","fa":"هر دو نکته‌ی اصلی را در نمای کلی بگذار و بعد هر کدام را در پاراگراف خودش پشتیبانی کن."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Comparing figures","tr":"Rakamları karşılaştırmak","fa":"مقایسه‌ی عددها"},"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["X fell to ... before recovering to ...","fell to 5 before recovering to 6"],["X overtook Y","older members overtook younger ones"],["the highest / lowest figure was ...","the lowest figure was 41%"],["just over / well under half","well under half were satisfied"],["A and B, respectively","82% and 41%, respectively"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One body sentence, step by step","tr":"Bir gövde cümlesi, adım adım","fa":"یک جمله‌ی بدنه، قدم به قدم"},"instruction":"Table: satisfaction with a library. Books 88%, computers 52%, opening hours 39%.","item":"Write one sentence about the table.","answer":"While 88% of users were satisfied with the books, well under half (39%) were happy with the opening hours.","walk":[{"en":"Choose the highest (88%) and the lowest (39%).","tr":"En yükseği (%88) ve en düşüğü (%39) seç.","fa":"بالاترین (۸۸٪) و پایین‌ترین (۳۹٪) را انتخاب کن."},{"en":"Contrast them with \"while\".","tr":"Onları \"while\" ile karşılaştır.","fa":"با «while» آن‌ها را در برابر هم بگذار."},{"en":"Use \"well under half\" to give the meaning of the low figure.","tr":"Düşük rakamın anlamını vermek için \"well under half\" kullan.","fa":"از «well under half» استفاده کن تا معنی عدد پایین را بگویی."}]},"quick":{"prompt":"Which sentence is correct for a bar chart over time?","options":["The figure fell to 3 in 2021 before rising again.","The figure fell at 3 in 2021 before rising again.","The figure fell of 3 in 2021 before rising again."],"correct":0,"why":{"en":"\"Fell to\" gives the new level; \"at\" and \"of\" are wrong after \"fell\".","tr":"\"Fell to\" yeni seviyeyi verir; \"fell\"den sonra \"at\" ve \"of\" yanlış.","fa":"«fell to» سطح جدید را می‌دهد؛ «at» و «of» بعد از «fell» غلط‌اند."}},"remember":{"en":"Cover both visuals: one overview with a main point from each, then one paragraph each, with compared figures.","tr":"İki görseli de ele al: her birinden bir ana noktayla tek bir genel bakış, sonra her biri için karşılaştırılmış rakamlarla bir paragraf.","fa":"هر دو تصویر را پوشش بده: یک نمای کلی با یک نکته‌ی اصلی از هر کدام و بعد برای هر کدام یک پاراگراف با عددهای مقایسه‌شده."},"type":"explain","id":"c-x04-w1-e","course":"ielts-exams","exam":"exam-04","unit":"x04-w1"},"writing":{"taskKind":"exam","title":{"en":"Describe the chart and the table: a sports centre","tr":"Grafiği ve tabloyu anlat: bir spor merkezi","fa":"نمودار و جدول را توصیف کن: یک مرکز ورزشی"},"task":"task1-academic","reviewLabel":{"en":"Exam 4 · Writing Task 1 Academic (bar chart + table: sports-centre visits and satisfaction)"},"timed":20,"minWords":150,"ctx":["W1-mixed"],"chart":{"type":"mixed","title":"A sports centre: visits by age group, 2019-2025, and satisfaction with facilities, 2025","parts":[{"type":"bar","title":"Average visits per member per month, by age group, 2019-2025","unit":"visits per month","labels":["2019","2021","2023","2025"],"series":[{"name":"16-24","values":[9,6,8,10]},{"name":"25-49","values":[7,5,6,6]},{"name":"50 and over","values":[4,3,6,8]}]},{"type":"table","title":"Members satisfied with each facility, 2025 (%)","headers":["Facility","% satisfied"],"rows":[["Pool","82"],["Classes","74"],["Gym","65"],["Changing rooms","48"],["Café","41"]]}]},"prompt":{"en":"You should spend about 20 minutes on this task. The bar chart below shows the average number of visits per month made by members of three age groups to a sports centre between 2019 and 2025. The table shows the percentage of members who were satisfied with five facilities in 2025. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.","tr":"Bu göreve yaklaşık 20 dakika ayırmalısın. Aşağıdaki sütun grafik, 2019 ile 2025 arasında üç yaş grubundaki üyelerin bir spor merkezine ayda ortalama kaç kez gittiğini gösteriyor. Tablo, 2025’te beş olanaktan memnun olan üyelerin yüzdesini gösteriyor. Ana özellikleri seçip aktararak bilgiyi özetle ve gerekli yerlerde karşılaştırma yap. En az 150 kelime yaz.","fa":"باید حدود ۲۰ دقیقه برای این تکلیف وقت بگذاری. نمودار میله‌ای زیر میانگین تعداد بازدید ماهانه‌ی اعضای سه گروه سنی از یک مرکز ورزشی را بین ۲۰۱۹ و ۲۰۲۵ نشان می‌دهد. جدول درصد اعضایی را نشان می‌دهد که در ۲۰۲۵ از پنج امکانات راضی بودند. اطلاعات را با انتخاب و گزارش ویژگی‌های اصلی خلاصه کن و هرجا لازم است مقایسه کن. دست‌کم ۱۵۰ کلمه بنویس."},"model":"The bar chart shows how many times a month, on average, members of three age groups visited a sports centre between 2019 and 2025, while the table shows how satisfied members were with five of its facilities in 2025.\n\nOverall, visits fell in all three groups in 2021 and then recovered, with the over-50s showing the strongest growth. The table shows that members were generally happy with the sports facilities but much less satisfied with the café and the changing rooms.\n\nIn 2019, the youngest members, aged 16 to 24, visited most often, at nine times a month, compared with seven for those aged 25 to 49 and only four for the over-50s. All three figures dropped in 2021, to six, five and three respectively. After that, visits by the youngest group rose to ten by 2025, while the middle group levelled off at six. The over-50s doubled their visits, from four to eight, and almost caught up with the youngest members.\n\nAs for satisfaction, the pool received the highest rating, at 82%, followed by classes (74%) and the gym (65%). In contrast, fewer than half of members were satisfied with the changing rooms (48%) and the café (41%).","moves":[{"label":{"en":"1 What the two visuals show","tr":"1 İki görsel ne gösteriyor","fa":"۱ دو تصویر چه نشان می‌دهند"},"text":"The bar chart shows how many times a month... while the table shows how satisfied members were..."},{"label":{"en":"2 Overview: one main point from each","tr":"2 Genel bakış: her birinden bir ana nokta","fa":"۲ نمای کلی: یک نکته‌ی اصلی از هر کدام"},"text":"Overall, visits fell in all three groups in 2021 and then recovered... much less satisfied with the café and the changing rooms."},{"label":{"en":"3 Body 1: the bar chart","tr":"3 Gövde 1: sütun grafik","fa":"۳ بدنه ۱: نمودار میله‌ای"},"text":"In 2019, the youngest members... The over-50s doubled their visits, from four to eight..."},{"label":{"en":"4 Body 2: the table","tr":"4 Gövde 2: tablo","fa":"۴ بدنه ۲: جدول"},"text":"As for satisfaction, the pool received the highest rating, at 82%... In contrast, fewer than half..."}],"rubricBands":{"note":{"en":"Score each line from 0 to 3. Read the line for the score you choose: it tells you what to improve next.","tr":"Her satırı 0’dan 3’e puanla. Seçtiğin puanın satırını oku: bir sonraki adımda neyi geliştireceğini söyler.","fa":"به هر خط از ۰ تا ۳ نمره بده. توضیحِ نمره‌ای را که انتخاب می‌کنی بخوان: می‌گوید قدم بعدی چه چیزی را بهتر کنی."},"order":["task","organised","words","sentences"],"task":[{"en":"No overview, and key figures are missing or wrong.","tr":"Genel bakış yok; önemli rakamlar eksik ya da yanlış.","fa":"نمای کلی ندارد و عددهای مهم جا افتاده یا غلط‌اند."},{"en":"Some key features, but no clear overview, or every figure listed.","tr":"Bazı önemli noktalar var ama net bir genel bakış yok ya da her rakam sıralanmış.","fa":"بعضی نکته‌های مهم هست، اما نمای کلی روشنی نیست یا همه‌ی عددها فهرست شده‌اند."},{"en":"A clear overview and most key features, with figures.","tr":"Net bir genel bakış ve önemli noktaların çoğu, rakamlarla.","fa":"نمای کلی روشن و بیشترِ نکته‌های مهم، با عدد."},{"en":"A clear overview; all key features chosen well, compared, with accurate figures.","tr":"Net bir genel bakış; tüm önemli noktalar iyi seçilmiş, karşılaştırılmış, rakamlar doğru.","fa":"نمای کلی روشن؛ همه‌ی نکته‌های مهم خوب انتخاب و مقایسه شده‌اند و عددها دقیق‌اند."}],"organised":[{"en":"No paragraphs; ideas jump around.","tr":"Paragraf yok; fikirler bir yerden bir yere atlıyor.","fa":"پاراگراف ندارد؛ ایده‌ها پراکنده‌اند."},{"en":"Paragraphs, but the data is described item by item.","tr":"Paragraflar var ama veriler tek tek anlatılmış.","fa":"پاراگراف دارد، اما داده‌ها مورد به مورد توصیف شده‌اند."},{"en":"Introduction, overview and body paragraphs grouped by pattern.","tr":"Giriş, genel bakış ve örüntüye göre gruplanmış gövde paragrafları.","fa":"مقدمه، نمای کلی و پاراگراف‌هایی که بر اساس الگو دسته‌بندی شده‌اند."},{"en":"Every paragraph has one clear job; linking words are natural and varied.","tr":"Her paragrafın net bir işi var; bağlaçlar doğal ve çeşitli.","fa":"هر پاراگراف یک کار روشن دارد؛ کلمه‌های ربط طبیعی و متنوع‌اند."}],"words":[{"en":"Very few words for change; the question is copied.","tr":"Değişim için çok az kelime; soru kopyalanmış.","fa":"کلمه‌های خیلی کمی برای تغییر؛ صورت سؤال کپی شده."},{"en":"The same few words (increase, decrease) again and again.","tr":"Aynı birkaç kelime (increase, decrease) tekrar tekrar.","fa":"همان چند کلمه (increase، decrease) مدام تکرار شده."},{"en":"Varied words for change and comparison, with a few errors.","tr":"Değişim ve karşılaştırma için çeşitli kelimeler, birkaç hatayla.","fa":"کلمه‌های متنوع برای تغییر و مقایسه، با چند غلط."},{"en":"Precise, varied words for trends and comparison, almost no errors.","tr":"Eğilim ve karşılaştırma için kesin, çeşitli kelimeler, neredeyse hatasız.","fa":"کلمه‌های دقیق و متنوع برای روند و مقایسه، تقریباً بی‌غلط."}],"sentences":[{"en":"Mostly short sentences with frequent errors.","tr":"Çoğunlukla kısa cümleler, sık hatalar.","fa":"بیشتر جمله‌های کوتاه با غلط‌های زیاد."},{"en":"Some longer sentences; errors sometimes make the meaning unclear.","tr":"Bazı uzun cümleler; hatalar bazen anlamı belirsizleştiriyor.","fa":"چند جمله‌ی بلندتر؛ غلط‌ها گاهی معنی را نامفهوم می‌کنند."},{"en":"A mix of sentence types; errors rarely affect the meaning.","tr":"Çeşitli cümle türleri; hatalar anlamı nadiren etkiliyor.","fa":"ترکیبی از انواع جمله؛ غلط‌ها به‌ندرت روی معنی اثر می‌گذارند."},{"en":"A wide range of sentences, almost all accurate.","tr":"Çok çeşitli cümleler, neredeyse hepsi doğru.","fa":"جمله‌های خیلی متنوع، تقریباً همه درست."}]},"rubric":["Covers the task: an overview of both visuals, with the key features and accurate figures from each.","Organised: an introduction, an overview, then one body paragraph for each visual.","Words: varied language for change and comparison, spelled correctly; the prompt is not copied.","Sentences: a mix of simple and complex sentences; tenses and the prepositions to and by used correctly."],"rubricI18n":{"tr":["Görevi karşılıyor: iki görselin genel bakışı, her birinden önemli özellikler ve doğru rakamlar.","Düzenli: giriş, genel bakış, sonra her görsel için bir gövde paragrafı.","Kelimeler: değişim ve karşılaştırma için çeşitli ifadeler, doğru yazılmış; soru metni kopyalanmamış.","Cümleler: basit ve karmaşık cümlelerin karışımı; zamanlar ve to ile by edatları doğru kullanılmış."],"fa":["تکلیف را پوشش می‌دهد: نمای کلیِ هر دو تصویر، با ویژگی‌های مهم و عددهای دقیق از هر کدام.","منظم است: مقدمه، نمای کلی و بعد برای هر تصویر یک پاراگراف.","کلمه‌ها: زبان متنوع برای تغییر و مقایسه، با املای درست؛ متن سؤال کپی نشده.","جمله‌ها: ترکیبی از جمله‌های ساده و مرکب؛ زمان‌ها و حرف‌های اضافه‌ی to و by درست به کار رفته‌اند."]},"type":"writing","id":"c-x04-w1-w","course":"ielts-exams","exam":"exam-04","unit":"x04-w1"},"exit":{"type":"exit","items":[{"tests":"word","point":3,"prompt":"\"Visits levelled off at six a month.\" Levelled off means...","options":["rose sharply","fell to zero","stopped changing"],"correct":2,"why":{"en":"To level off = to stay at about the same level after rising or falling.","tr":"Level off = yükselip düştükten sonra aşağı yukarı aynı seviyede kalmak.","fa":"level off یعنی بعد از بالا یا پایین رفتن تقریباً در همان سطح ماندن."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase means \"fewer than 50%\"?","options":["just over half","under half","the majority"],"correct":1,"why":{"en":"Under half = less than 50%; the majority means more than half.","tr":"Under half = %50’den az; the majority yarıdan fazla demektir.","fa":"under half یعنی کمتر از ۵۰٪؛ the majority یعنی بیشتر از نصف."}},{"tests":"method","point":1,"prompt":"A task has a bar chart and a table. What should the overview contain?","options":["one main point from each visual","only the main point of the chart","every figure in the table"],"correct":0,"why":{"en":"Both visuals must appear in the overview; details come later.","tr":"İki görsel de genel bakışta yer almalı; ayrıntılar sonra gelir.","fa":"هر دو تصویر باید در نمای کلی بیایند؛ جزئیات بعداً می‌آیند."}},{"tests":"trap","point":2,"prompt":"A student writes: \"Older members visited more because they liked the pool.\" What is wrong?","options":["It uses the wrong tense","It gives too many figures","It links the visuals with a reason the data does not show"],"correct":2,"why":{"en":"The data shows visits and satisfaction, not why people visited. Do not invent causes.","tr":"Veri ziyaretleri ve memnuniyeti gösteriyor, insanların neden geldiğini değil. Neden uydurma.","fa":"داده‌ها بازدید و رضایت را نشان می‌دهند، نه دلیل آمدن آدم‌ها را. علت نساز."}}],"id":"c-x04-w1-x","course":"ielts-exams","exam":"exam-04","unit":"x04-w1"},"gt":{"explain":{"title":{"en":"Writing Task 1: a letter offering help","tr":"Writing Task 1: yardım teklif eden bir mektup","fa":"Writing Task 1: نامه‌ی پیشنهاد کمک"},"objective":{"en":"In this lesson you will learn to write a semi-formal letter offering help: a polite, friendly tone for someone you know a little, one paragraph for each bullet point with exact details, and a suitable close, in at least 150 words.","tr":"Bu derste yardım teklif eden yarı resmî bir mektup yazmayı öğreneceksin: biraz tanıdığın biri için kibar ve samimi bir üslup, her madde için kesin ayrıntılarla bir paragraf ve uygun bir kapanış, en az 150 kelimeyle.","fa":"در این درس یاد می‌گیری یک نامه‌ی نیمه‌رسمی برای پیشنهاد کمک بنویسی: لحنی مؤدب و دوستانه برای کسی که کمی می‌شناسی‌اش، برای هر نکته یک پاراگراف با جزئیات دقیق و پایانی مناسب، در دست‌کم ۱۵۰ کلمه."},"stats":[{"label":{"en":"Words","tr":"Kelime","fa":"کلمه"},"value":"150+"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}},{"label":{"en":"Bullet points","tr":"Madde","fa":"نکته‌ها"},"value":"3"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: helping at a street party","tr":"Bu sınav: bir sokak şenliğine yardım","fa":"این آزمون: کمک در یک جشن خیابانی"},"intro":{"en":"GT Task 1 is a letter with three bullet points. Some readers are strangers (formal), some are friends (informal), and some are in between: a neighbour, an organiser or a colleague. For them, write a semi-formal letter.","tr":"GT Task 1 üç maddeli bir mektuptur. Bazı okurlar yabancıdır (resmî), bazıları arkadaştır (samimi), bazıları da arada: bir komşu, bir düzenleyici ya da bir iş arkadaşı. Onlar için yarı resmî bir mektup yaz.","fa":"GT Task 1 نامه‌ای با سه نکته است. بعضی خواننده‌ها غریبه‌اند (رسمی)، بعضی دوست (دوستانه) و بعضی بینابین: یک همسایه، یک برگزارکننده یا یک همکار. برای آن‌ها نامه‌ی نیمه‌رسمی بنویس."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x04-w1gt-ctx","exam":true,"patterns":["W1-offer","REG-semi","PARA-letter"],"often":{"pattern":"W1-offer","n":7,"of":36,"label":{"en":"Comes up often in the real exam: 7 of the last 36 letters","tr":"Gerçek sınavda sık çıkar: son 36 mektubun 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ نامه از ۳۶ نامه‌ی اخیر"}},"title":{"en":"Offering to help at a local event","tr":"Yerel bir etkinlikte yardım teklif etmek","fa":"پیشنهاد کمک در یک برنامه‌ی محلی"},"asks":{"en":"You write to the organiser of a neighbourhood event, someone you know a little, to offer your help: what the event is and how you heard about it, what you could do, and when you are free. Offers and invitations are one of the four most frequent GT letters.","tr":"Bir mahalle etkinliğinin düzenleyicisine, biraz tanıdığın birine, yardım teklif etmek için yazıyorsun: etkinlik ne ve nereden duydun, ne yapabilirsin ve ne zaman boşsun. Teklif ve davet mektupları en sık çıkan dört GT mektup türünden biridir.","fa":"برای برگزارکننده‌ی یک برنامه‌ی محلی، کسی که کمی می‌شناسی‌اش، می‌نویسی تا کمک پیشنهاد بدهی: برنامه چیست و از کجا خبردار شدی، چه کاری از دستت برمی‌آید و کی وقت آزاد داری. نامه‌های پیشنهاد و دعوت یکی از چهار نوع پرتکرار نامه در GT هستند."},"fields":["Opening","The event and how you heard","What you can do","When you are free","Close"],"words":[{"a":"I’m writing to offer","b":"I’d be happy to help with","tr":"... teklif etmek için yazıyorum","fa":"می‌نویسم تا ... را پیشنهاد بدهم"},{"a":"I saw the notice","b":"I read about it in the newsletter","tr":"duyuruyu gördüm","fa":"اطلاعیه را دیدم"},{"a":"I have some experience of","b":"I have done this before","tr":"... konusunda biraz deneyimim var","fa":"در ... کمی تجربه دارم"},{"a":"set up","b":"put up tables, tents and signs","tr":"kurmak","fa":"برپا کردن"},{"a":"clear up","b":"tidy everything away afterwards","tr":"toplamak, temizlemek","fa":"جمع‌وجور کردن"},{"a":"I’m free on","b":"I’m available on","tr":"... boşum","fa":"... وقتم آزاد است"},{"a":"unfortunately","b":"I’m afraid","tr":"ne yazık ki","fa":"متأسفانه"},{"a":"let me know","b":"tell me","tr":"bana haber ver","fa":"خبرم کن"},{"a":"Best regards","b":"Kind regards","tr":"Saygılarımla (yarı resmî)","fa":"با احترام (نیمه‌رسمی)"},{"a":"semi-formal","b":"polite but friendly","tr":"yarı resmî","fa":"نیمه‌رسمی"}],"traps":[{"en":"The wrong register. You know the reader a little: use their name (\"Dear Mr Pemberton\"), polite but friendly language and \"Best regards\", not \"Yours faithfully\" or \"Love\".","tr":"Yanlış üslup. Okuru biraz tanıyorsun: adını kullan (\"Dear Mr Pemberton\"), kibar ama samimi bir dil ve \"Best regards\"; \"Yours faithfully\" ya da \"Love\" değil.","fa":"لحن غلط. خواننده را کمی می‌شناسی: اسمش را بنویس («Dear Mr Pemberton»)، زبانی مؤدب ولی گرم و «Best regards»، نه «Yours faithfully» یا «Love»."},{"en":"A vague offer. \"I can help with anything\" is thin; say exactly what you can do and why you are good at it.","tr":"Belirsiz bir teklif. \"Her şeye yardım edebilirim\" zayıf; tam olarak ne yapabileceğini ve neden bunda iyi olduğunu söyle.","fa":"پیشنهاد مبهم. «در هر کاری کمک می‌کنم» ضعیف است؛ دقیق بگو چه کاری از دستت برمی‌آید و چرا در آن خوبی."}],"example":{"text":"Bullet: explain how you could help.","item":"Write one semi-formal sentence.","answer":"I used to run a café, so I’d be happy to organise the refreshment stall and make sure there is enough tea for everyone.","why":{"en":"A clear task, a reason you are suited to it, and a polite, friendly tone.","tr":"Net bir görev, buna neden uygun olduğun ve kibar, samimi bir üslup.","fa":"یک کار روشن، دلیل مناسب بودنت و لحنی مؤدب و دوستانه."}}},{"id":"W1-offer","ctx":["W1-offer"],"title":{"en":"Offering, inviting, thanking or giving a view","tr":"Teklif etmek, davet etmek, teşekkür etmek ya da görüş bildirmek","fa":"پیشنهاد دادن، دعوت کردن، تشکر یا اظهار نظر"},"asks":{"en":"You write to an editor, a performer, an organiser or a company: invite someone to an event, offer something, thank them, correct an article or give your opinion. Formal or semi-formal.","tr":"Bir editöre, bir sanatçıya, bir organizatöre ya da bir şirkete yazarsın: birini bir etkinliğe davet edersin, bir şey teklif edersin, teşekkür edersin, bir makaleyi düzeltirsin ya da görüşünü bildirirsin. Resmî ya da yarı resmî.","fa":"به یک سردبیر، یک هنرمند، یک برگزارکننده یا یک شرکت نامه می‌نویسی: کسی را به رویدادی دعوت می‌کنی، چیزی پیشنهاد می‌دهی، تشکر می‌کنی، مقاله‌ای را اصلاح می‌کنی یا نظرت را می‌گویی. رسمی یا نیمه‌رسمی."},"fields":["Purpose: I am writing to invite you to... / to thank you for... / in response to your article","The details or the reasons","What you offer or suggest","A polite close"],"words":[{"a":"come to our event","b":"I would like to invite you to","tr":"... davet etmek isterim","fa":"مایلم ... را دعوت کنم"},{"a":"thank you","b":"I am writing to thank you for","tr":"teşekkür etmek için yazıyorum","fa":"برای تشکر می‌نویسم"},{"a":"I can bring","b":"I would be happy to provide","tr":"... sağlamaktan memnuniyet duyarım","fa":"خوشحال می‌شوم ... را فراهم کنم"},{"a":"your article is wrong","b":"I would like to point out some errors in","tr":"... bazı hatalara dikkat çekmek isterim","fa":"مایلم به چند اشتباه در ... اشاره کنم"},{"a":"I agree","b":"I fully support the view that","tr":"... görüşünü tamamen destekliyorum","fa":"کاملاً با این نظر موافقم که"},{"a":"it was great","b":"it was a truly memorable evening","tr":"gerçekten unutulmaz bir akşamdı","fa":"شبی واقعاً به‌یادماندنی بود"},{"a":"it changed me","b":"it inspired me to","tr":"bana ... için ilham verdi","fa":"به من انگیزه داد که"},{"a":"you are right for it","b":"you would be the ideal person to","tr":"... için en uygun kişi","fa":"بهترین فرد برای"},{"a":"the event","b":"the opening / the festival","tr":"açılış, festival","fa":"افتتاحیه، جشنواره"},{"a":"when","b":"it will take place on","tr":"... tarihinde yapılacak","fa":"در تاریخ ... برگزار می‌شود"},{"a":"I suggest","b":"I would recommend that","tr":"... önermek isterim","fa":"پیشنهاد می‌کنم که"},{"a":"please say yes","b":"I very much hope you will be able to accept","tr":"kabul edebileceğinizi umuyorum","fa":"امیدوارم دعوت پذیرفته شود"}],"traps":[{"en":"Know the reader: a famous performer you have never met needs formal language, even when you are excited.","tr":"Okuru tanı: hiç tanışmadığın ünlü bir sanatçıya, heyecanlı olsan bile resmî dille yazılır.","fa":"خواننده را بشناس: برای هنرمند مشهوری که هیچ‌وقت ندیده‌ای، حتی اگر هیجان‌زده‌ای، زبان رسمی لازم است."},{"en":"Correcting an article: be precise and polite, and give the right facts, not just \"it is wrong\".","tr":"Bir makaleyi düzeltirken: kesin ve kibar ol, yalnızca \"yanlış\" deme, doğru bilgiyi ver.","fa":"اصلاح یک مقاله: دقیق و مؤدب باش و اطلاعات درست را بده، نه فقط «اشتباه است»."}],"example":{"text":"Bullet: \"explain why you are inviting this person\".","item":"Which sentence answers it?  A Please come.   B As our town’s best-known actor, you would be the ideal person to open the theatre where you first performed as a child.   C The theatre has 300 seats.","answer":"B","why":{"en":"B gives a reason linked to this person. A has no reason; C is a detail for another bullet.","tr":"B bu kişiyle bağlantılı bir neden veriyor. A’da neden yok; C başka bir madde için ayrıntı.","fa":"B دلیلی مرتبط با همین شخص می‌دهد. A دلیلی ندارد؛ C جزئیاتی برای بند دیگری است."}},"general":true,"patterns":["W1-offer"],"often":{"pattern":"W1-offer","n":7,"of":36,"label":{"en":"Comes up often in the real exam: 7 of the last 36 letters","tr":"Gerçek sınavda sık çıkar: son 36 mektubun 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ نامه از ۳۶ نامه‌ی اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Name, purpose, three paragraphs","tr":"Ad, amaç, üç paragraf","fa":"اسم، هدف، سه پاراگراف"},"body":{"en":"Write at least 150 words in about 20 minutes. Begin with the reader’s title and surname (\"Dear Mr Pemberton,\"), state your purpose early, give each bullet its own paragraph, and close with \"Best regards\" or \"Kind regards\".","tr":"Yaklaşık 20 dakikada en az 150 kelime yaz. Okurun unvanı ve soyadıyla başla (\"Dear Mr Pemberton,\"), amacını erkenden söyle, her maddeye ayrı bir paragraf ver ve \"Best regards\" ya da \"Kind regards\" ile bitir.","fa":"در حدود ۲۰ دقیقه دست‌کم ۱۵۰ کلمه بنویس. با عنوان و نام خانوادگی خواننده شروع کن («Dear Mr Pemberton,»)، هدفت را زود بگو، برای هر نکته یک پاراگراف جدا بنویس و با «Best regards» یا «Kind regards» تمام کن."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Make the offer useful","tr":"Teklifi işe yarar kıl","fa":"پیشنهادت را مفید کن"},"steps":[{"en":"Bullet 1: name the event and say exactly how you heard about it.","tr":"Madde 1: etkinliğin adını ver ve nereden duyduğunu tam olarak söyle.","fa":"نکته‌ی ۱: اسم برنامه را بگو و دقیق بگو از کجا خبردار شدی."},{"en":"Bullet 2: offer one or two clear tasks and give a reason you can do them well.","tr":"Madde 2: bir iki net görev teklif et ve bunları neden iyi yapabileceğini söyle.","fa":"نکته‌ی ۲: یکی دو کار روشن پیشنهاد بده و دلیل بیاور که چرا خوب انجامشان می‌دهی."},{"en":"Bullet 3: give days and times, and one limit if you have one.","tr":"Madde 3: günleri ve saatleri ver; varsa bir sınırlamayı da söyle.","fa":"نکته‌ی ۳: روزها و ساعت‌ها را بگو و اگر محدودیتی داری آن را هم بگو."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Between formal and informal","tr":"Resmî ile samimi arasında","fa":"بین رسمی و دوستانه"},"body":{"en":"A semi-formal letter can use contractions and friendly phrases (\"I’d be happy to\"), but not slang or very casual language. Do not end with \"Yours faithfully\", which is for strangers, or \"Love\", which is for close friends.","tr":"Yarı resmî bir mektup kısaltmalar ve samimi ifadeler (\"I’d be happy to\") kullanabilir ama argo ya da çok gündelik bir dil kullanmaz. Yabancılar için olan \"Yours faithfully\" ile ya da yakın arkadaşlar için olan \"Love\" ile bitirme.","fa":"نامه‌ی نیمه‌رسمی می‌تواند شکل‌های کوتاه و عبارت‌های دوستانه («I’d be happy to») داشته باشد، اما نه زبان عامیانه یا خیلی خودمانی. با «Yours faithfully» که مال غریبه‌هاست یا «Love» که مال دوست‌های نزدیک است تمام نکن."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"The opening, step by step","tr":"Açılış, adım adım","fa":"شروع نامه، قدم به قدم"},"instruction":"You want to offer to help at your child’s school sports day. Write to the teacher who is organising it.","item":"Write the greeting and the first sentence.","answer":"Dear Ms Rahman, I saw the notice about sports day in the school newsletter, and I’d be happy to help on the day.","walk":[{"en":"You know the teacher a little: title and surname.","tr":"Öğretmeni biraz tanıyorsun: unvan ve soyadı.","fa":"معلم را کمی می‌شناسی: عنوان و نام خانوادگی."},{"en":"Say how you heard about the event: the newsletter.","tr":"Etkinliği nereden duyduğunu söyle: okul bülteni.","fa":"بگو از کجا درباره‌ی برنامه شنیدی: خبرنامه‌ی مدرسه."},{"en":"Give your purpose in a friendly way: \"I’d be happy to help\".","tr":"Amacını samimi bir şekilde ver: \"I’d be happy to help\".","fa":"هدفت را دوستانه بگو: «I’d be happy to help»."}]},"quick":{"prompt":"Which closing suits a letter to a neighbour you know a little?","options":["Yours faithfully, Ali Karimi","Best regards, Ali Karimi","Lots of love, Ali"],"correct":1,"why":{"en":"\"Best regards\" is polite and friendly: right for a semi-formal letter.","tr":"\"Best regards\" kibar ve samimi: yarı resmî bir mektup için doğru.","fa":"«Best regards» مؤدب و دوستانه است: درست برای نامه‌ی نیمه‌رسمی."}},"remember":{"en":"Use the reader’s name, offer exact tasks with reasons, give your times, and close with \"Best regards\".","tr":"Okurun adını kullan, nedenleriyle kesin görevler teklif et, zamanlarını ver ve \"Best regards\" ile bitir.","fa":"اسم خواننده را بنویس، کارهای دقیق با دلیل پیشنهاد بده، زمان‌هایت را بگو و با «Best regards» تمام کن."},"type":"explain","id":"c-x04-w1-e-gt","course":"ielts-exams","exam":"exam-04","unit":"x04-w1"},"writing":{"taskKind":"exam","title":{"en":"Offer to help at a neighbourhood event","tr":"Bir mahalle etkinliğinde yardım teklif et","fa":"در یک برنامه‌ی محلی پیشنهاد کمک بده"},"task":"task1-gt","reviewLabel":{"en":"Exam 4 · Writing Task 1 GT (semi-formal letter: offering to help at a neighbourhood event)"},"timed":20,"minWords":150,"ctx":["W1-offer","REG-semi"],"bullets":["say how you heard about the event","explain what you could do to help","say when you are available"],"prompt":{"en":"You should spend about 20 minutes on this task. Your neighbourhood is organising a street party, and a neighbour, Mr Pemberton, is in charge. Write a letter to Mr Pemberton offering to help. In your letter: say how you heard about the event; explain what you could do to help; say when you are available. Write at least 150 words. You do NOT need to write any addresses. Begin your letter as follows: Dear Mr Pemberton,","tr":"Bu göreve yaklaşık 20 dakika ayırmalısın. Mahallen bir sokak şenliği düzenliyor ve sorumlusu komşun Bay Pemberton. Bay Pemberton’a yardım teklif eden bir mektup yaz. Mektubunda: etkinliği nereden duyduğunu söyle; yardım için neler yapabileceğini açıkla; ne zaman müsait olduğunu söyle. En az 150 kelime yaz. Adres yazmana gerek yok. Mektuba şöyle başla: Dear Mr Pemberton,","fa":"باید حدود ۲۰ دقیقه برای این تکلیف وقت بگذاری. محله‌ات یک جشن خیابانی برگزار می‌کند و مسئولش یکی از همسایه‌هاست به اسم آقای پمبرتون. برای آقای پمبرتون نامه بنویس و پیشنهاد کمک بده. در نامه‌ات: بگو از کجا درباره‌ی این برنامه شنیدی؛ توضیح بده چه کمکی از دستت برمی‌آید؛ بگو کی وقت داری. دست‌کم ۱۵۰ کلمه بنویس. لازم نیست آدرسی بنویسی. نامه را این‌طور شروع کن: Dear Mr Pemberton,"},"model":"Dear Mr Pemberton,\n\nI saw the notice about the Linden Grove street party in last week's residents' newsletter, and I'm writing to offer my help. My family moved into number 14 in the spring, and we think it's a lovely way to get to know our neighbours.\n\nI worked as a primary school teacher for several years, so I'd be happy to organise some games for the children. I could run a treasure hunt in the afternoon and a face-painting table, and I already have most of the materials we would need. If you need help with anything else, such as setting up tables or clearing up afterwards, I'd be glad to do that too.\n\nAs for timing, I'm free all day on the Saturday of the party, and I could also come to a planning meeting on any weekday evening after six. Unfortunately, I'll be away the weekend before, so I won't be able to help with the shopping.\n\nPlease let me know if this would be useful and what you would like me to do. I'm really looking forward to it.\n\nBest regards,\nCarla Ferreira","moves":[{"label":{"en":"1 How you heard, and the purpose","tr":"1 Nereden duydun ve amaç","fa":"۱ از کجا شنیدی و هدف"},"text":"I saw the notice about the Linden Grove street party in last week’s residents’ newsletter, and I’m writing to offer my help."},{"label":{"en":"2 Bullet 2: exact tasks, with a reason","tr":"2 Madde 2: kesin görevler, bir nedenle","fa":"۲ نکته‌ی ۲: کارهای دقیق، با دلیل"},"text":"I worked as a primary school teacher... so I’d be happy to organise some games for the children."},{"label":{"en":"3 Bullet 3: days, times and one limit","tr":"3 Madde 3: günler, saatler ve bir sınırlama","fa":"۳ نکته‌ی ۳: روزها، ساعت‌ها و یک محدودیت"},"text":"I’m free all day on the Saturday of the party... Unfortunately, I’ll be away the weekend before..."},{"label":{"en":"4 A friendly, polite close","tr":"4 Samimi ve kibar bir kapanış","fa":"۴ پایانی دوستانه و مؤدبانه"},"text":"Please let me know if this would be useful... Best regards,"}],"rubricBands":{"note":{"en":"Score each line from 0 to 3. Read the line for the score you choose: it tells you what to improve next.","tr":"Her satırı 0’dan 3’e puanla. Seçtiğin puanın satırını oku: bir sonraki adımda neyi geliştireceğini söyler.","fa":"به هر خط از ۰ تا ۳ نمره بده. توضیحِ نمره‌ای را که انتخاب می‌کنی بخوان: می‌گوید قدم بعدی چه چیزی را بهتر کنی."},"order":["task","organised","words","sentences"],"task":[{"en":"The purpose is unclear and at least one bullet is missing.","tr":"Amaç belirsiz, en az bir madde eksik.","fa":"هدف روشن نیست و دست‌کم یک نکته جا افتاده."},{"en":"All bullets are mentioned, but one or two are very thin.","tr":"Tüm maddelerden söz edilmiş ama biri ya da ikisi çok zayıf.","fa":"به همه‌ی نکته‌ها اشاره شده، اما یکی دو تا خیلی ضعیف‌اند."},{"en":"The purpose is clear early and all three bullets are covered.","tr":"Amaç baştan net, üç madde de işlenmiş.","fa":"هدف از اول روشن است و هر سه نکته پوشش داده شده‌اند."},{"en":"Clear purpose; every bullet is fully developed with useful details.","tr":"Net amaç; her madde yararlı ayrıntılarla tam geliştirilmiş.","fa":"هدف روشن؛ هر نکته با جزئیات مفید کامل شده."}],"organised":[{"en":"No paragraphs; ideas jump around.","tr":"Paragraf yok; fikirler bir yerden bir yere atlıyor.","fa":"پاراگراف ندارد؛ ایده‌ها پراکنده‌اند."},{"en":"Paragraphs, but bullets are mixed together.","tr":"Paragraflar var ama maddeler birbirine karışmış.","fa":"پاراگراف دارد، اما نکته‌ها قاطی شده‌اند."},{"en":"An opening, one paragraph per bullet and a closing.","tr":"Bir açılış, her madde için bir paragraf ve bir kapanış.","fa":"یک شروع، یک پاراگراف برای هر نکته و یک پایان."},{"en":"Each paragraph has one clear job; the letter reads smoothly.","tr":"Her paragrafın net bir işi var; mektup akıcı okunuyor.","fa":"هر پاراگراف یک کار روشن دارد؛ نامه روان خوانده می‌شود."}],"words":[{"en":"The tone does not suit the reader at all, and words are very basic.","tr":"Üslup okura hiç uymuyor, kelimeler çok temel.","fa":"لحن اصلاً به خواننده نمی‌خورد و کلمه‌ها خیلی ساده‌اند."},{"en":"The tone changes between formal and casual; simple words are repeated.","tr":"Üslup resmî ile samimi arasında gidip geliyor; basit kelimeler tekrarlanıyor.","fa":"لحن بین رسمی و خودمانی عوض می‌شود و کلمه‌های ساده تکرار می‌شوند."},{"en":"The tone suits the reader; suitable phrases for the purpose of the letter, with a few errors.","tr":"Üslup okura uygun; mektubun amacına uygun ifadeler, birkaç hata.","fa":"لحن مناسب خواننده است؛ عبارت‌های مناسب برای هدفِ نامه، با چند غلط."},{"en":"The right tone from the first line to the last, with natural, precise phrases.","tr":"İlk satırdan sona kadar doğru üslup, doğal ve yerinde ifadeler.","fa":"لحن درست از خط اول تا آخر، با عبارت‌های طبیعی و دقیق."}],"sentences":[{"en":"Mostly short sentences with frequent errors.","tr":"Çoğunlukla kısa cümleler, sık hatalar.","fa":"بیشتر جمله‌های کوتاه با غلط‌های زیاد."},{"en":"Some longer sentences; errors sometimes make the meaning unclear.","tr":"Bazı uzun cümleler; hatalar bazen anlamı belirsizleştiriyor.","fa":"چند جمله‌ی بلندتر؛ غلط‌ها گاهی معنی را نامفهوم می‌کنند."},{"en":"A mix of sentence types; errors rarely affect the meaning.","tr":"Çeşitli cümle türleri; hatalar anlamı nadiren etkiliyor.","fa":"ترکیبی از انواع جمله؛ غلط‌ها به‌ندرت روی معنی اثر می‌گذارند."},{"en":"A wide range of sentences, almost all accurate.","tr":"Çok çeşitli cümleler, neredeyse hepsi doğru.","fa":"جمله‌های خیلی متنوع، تقریباً همه درست."}]},"rubric":["Covers the task: the purpose is clear early and all three bullet points are fully covered.","Organised: one paragraph for each bullet point, with an opening and a closing that suit the reader.","Words: the right tone for the reader (formal, semi-formal or informal), with precise words.","Sentences: polite forms used correctly, a mix of sentence types and few errors."],"rubricI18n":{"tr":["Görevi karşılıyor: amaç en başta net ve üç maddenin üçü de tam olarak ele alınmış.","Düzenli: her madde için bir paragraf; okura uygun bir açılış ve kapanış.","Kelimeler: okura uygun ton (resmî, yarı resmî ya da samimi), yerinde kelimeler.","Cümleler: kibar kalıplar doğru kullanılmış, çeşitli cümle türleri ve az hata."],"fa":["تکلیف را پوشش می‌دهد: هدف از همان اول روشن است و هر سه نکته کامل پوشش داده شده‌اند.","منظم است: برای هر نکته یک پاراگراف، با شروع و پایانی که به خواننده می‌خورد.","کلمه‌ها: لحن مناسب برای خواننده (رسمی، نیمه‌رسمی یا دوستانه)، با کلمه‌های دقیق.","جمله‌ها: عبارت‌های مؤدبانه درست به کار رفته‌اند، ترکیبی از انواع جمله و اشتباه کم."]},"type":"writing","id":"c-x04-w1-w-gt","course":"ielts-exams","exam":"exam-04","unit":"x04-w1"},"exit":{"type":"exit","items":[{"tests":"word","point":3,"prompt":"\"I could help to set up the stalls.\" To set up means to...","options":["get them ready before the event","take them away afterwards","pay for them"],"correct":0,"why":{"en":"Set up = prepare and put in place; clear up = tidy away afterwards.","tr":"Set up = hazırlayıp yerine koymak; clear up = sonradan toplamak.","fa":"set up یعنی آماده کردن و سر جا گذاشتن؛ clear up یعنی بعداً جمع کردن."}},{"tests":"paraphrase","point":3,"prompt":"Which sentence is a friendly, semi-formal way to offer help?","options":["I hereby offer my services.","I can do games, whatever.","I’d be happy to help with the children’s games."],"correct":2,"why":{"en":"\"I’d be happy to\" is polite and warm; the others are too formal or too casual.","tr":"\"I’d be happy to\" kibar ve sıcak; diğerleri ya fazla resmî ya fazla gündelik.","fa":"«I’d be happy to» مؤدب و گرم است؛ بقیه یا خیلی رسمی‌اند یا خیلی خودمانی."}},{"tests":"method","point":2,"prompt":"Bullet 3 asks when you are available. What makes the answer complete?","options":["only \"I’m usually free\"","days, times and any limits","a list of your hobbies"],"correct":1,"why":{"en":"The organiser needs exact days and times, and to know when you cannot come.","tr":"Düzenleyicinin kesin günlere, saatlere ve ne zaman gelemeyeceğini bilmeye ihtiyacı var.","fa":"برگزارکننده روزها و ساعت‌های دقیق و اینکه کی نمی‌توانی بیایی را لازم دارد."}},{"tests":"trap","point":1,"prompt":"You are writing to a neighbour you know a little. Which pair of opening and closing is right?","options":["Dear Mr Pemberton, ... Best regards,","Dear Sir or Madam, ... Yours faithfully,","Hi Pete!! ... Love,"],"correct":0,"why":{"en":"A known name with a semi-formal close suits someone you know a little.","tr":"Bilinen bir ad ve yarı resmî bir kapanış, biraz tanıdığın birine uyar.","fa":"اسم آشنا با پایانی نیمه‌رسمی برای کسی که کمی می‌شناسی مناسب است."}}],"id":"c-x04-w1-x-gt","course":"ielts-exams","exam":"exam-04","unit":"x04-w1"}}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
